From df4d859a2ceb6159861b8c45ffdbb5ee30984aa9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:36:11 +0100
Subject: [PATCH] applet: add option to show battery percentage on the icon

The tray icon could only show the number of connected devices, so the
battery level of headphones was only visible in the tooltip or popup. A
new option fills the badge with the percentage when one device has one.

BUG: 528165
---
 src/applet/main.xml                   |  4 ++++
 src/applet/qml/FullRepresentation.qml |  2 ++
 src/applet/qml/Toolbar.qml            |  5 +++++
 src/applet/qml/main.qml               | 27 ++++++++++++++++++++++++---
 4 files changed, 35 insertions(+), 3 deletions(-)

diff --git a/src/applet/main.xml b/src/applet/main.xml
index b4f27269..5608a7b1 100644
--- a/src/applet/main.xml
+++ b/src/applet/main.xml
@@ -10,6 +10,10 @@
       <label>If true, the CompactRepresentation icon will display a badge with the number of connected devices.</label>
       <default>false</default>
     </entry>
+    <entry name="showBatteryPercentage" type="bool">
+      <label>If true and exactly one connected device reports its battery level, the CompactRepresentation icon will display a badge with that battery percentage.</label>
+      <default>false</default>
+    </entry>
   </group>

 </kcfg>
diff --git a/src/applet/qml/FullRepresentation.qml b/src/applet/qml/FullRepresentation.qml
index c281b129..6469495e 100644
--- a/src/applet/qml/FullRepresentation.qml
+++ b/src/applet/qml/FullRepresentation.qml
@@ -28,6 +28,7 @@ PlasmaExtras.Representation {
     required property PlasmaCore.Action addDeviceAction
     required property PlasmaCore.Action toggleBluetoothAction
     required property PlasmaCore.Action toggleBadgeAction
+    required property PlasmaCore.Action toggleBatteryBadgeAction
     required property PlasmaCore.Action configureAction

     readonly property bool emptyList: BluezQt.Manager.devices.length === 0
@@ -90,6 +91,7 @@ PlasmaExtras.Representation {
         addDeviceAction: root.addDeviceAction
         toggleBluetoothAction: root.toggleBluetoothAction
         toggleBadgeAction: root.toggleBadgeAction
+        toggleBatteryBadgeAction: root.toggleBatteryBadgeAction
         configureAction: root.configureAction

         visible: BluezQt.Manager.adapters.length > 0
diff --git a/src/applet/qml/Toolbar.qml b/src/applet/qml/Toolbar.qml
index ce3ecc9c..c75428df 100644
--- a/src/applet/qml/Toolbar.qml
+++ b/src/applet/qml/Toolbar.qml
@@ -25,6 +25,7 @@ PlasmaExtras.PlasmoidHeading {
     required property PlasmaCore.Action addDeviceAction
     required property PlasmaCore.Action toggleBluetoothAction
     required property PlasmaCore.Action toggleBadgeAction
+    required property PlasmaCore.Action toggleBatteryBadgeAction
     required property PlasmaCore.Action configureAction

     readonly property alias onSwitch: onSwitch
@@ -86,6 +87,10 @@ PlasmaExtras.PlasmoidHeading {
                 PlasmaExtras.MenuItem {
                     action: toggleBadgeAction
                 }
+
+                PlasmaExtras.MenuItem {
+                    action: toggleBatteryBadgeAction
+                }
             }

             visible: !(Plasmoid.containmentDisplayHints & PlasmaCore.Types.ContainmentDrawsPlasmoidHeading)
diff --git a/src/applet/qml/main.qml b/src/applet/qml/main.qml
index a9014a1a..a596b1bd 100644
--- a/src/applet/qml/main.qml
+++ b/src/applet/qml/main.qml
@@ -23,6 +23,7 @@ PlasmoidItem {
     readonly property alias addDeviceAction: addDeviceAction
     readonly property alias toggleBluetoothAction: toggleBluetoothAction
     readonly property alias toggleBadgeAction: toggleBadgeAction
+    readonly property alias toggleBatteryBadgeAction: toggleBatteryBadgeAction
     readonly property alias configureAction: configureAction

     switchWidth: Kirigami.Units.gridUnit * 15
@@ -33,6 +34,7 @@ PlasmoidItem {
         addDeviceAction: root.addDeviceAction
         toggleBluetoothAction: root.toggleBluetoothAction
         toggleBadgeAction: root.toggleBadgeAction
+        toggleBatteryBadgeAction: root.toggleBatteryBadgeAction
         configureAction: root.configureAction
     }

@@ -88,9 +90,17 @@ PlasmoidItem {
         }
     }

-    badgeText: Plasmoid.configuration.showNumberOfConnectedDevices && BluezQt.Manager.connectedDevices.length > 0
-        ? BluezQt.Manager.connectedDevices.length
-        : ""
+    badgeText: {
+        const connectedDevices = BluezQt.Manager.connectedDevices;
+        const devicesWithBattery = connectedDevices.filter(device => device.battery);
+        if (Plasmoid.configuration.showBatteryPercentage && devicesWithBattery.length === 1) {
+            return i18nc("@info:status battery percentage of the connected device, shown on the icon", "%1%", devicesWithBattery[0].battery.percentage);
+        }
+        if (Plasmoid.configuration.showNumberOfConnectedDevices && connectedDevices.length > 0) {
+            return connectedDevices.length;
+        }
+        return "";
+    }

     Plasmoid.onSecondaryActivated: {
         toggleBluetoothAction.trigger();
@@ -135,6 +145,17 @@ PlasmoidItem {
             onTriggered: checked => {
                 Plasmoid.configuration.showNumberOfConnectedDevices = checked;
             }
+        },
+        PlasmaCore.Action {
+            id: toggleBatteryBadgeAction
+            text: i18nc("@item:inmenu", "Show badge with battery percentage of the connected device")
+            icon.name: "format-number-percent"
+            alwaysShowAsMenu: true
+            checkable: true
+            checked: Plasmoid.configuration.showBatteryPercentage
+            onTriggered: checked => {
+                Plasmoid.configuration.showBatteryPercentage = checked;
+            }
         }
     ]

-- 
2.53.0
